"""Controlled decoding over the finite window universe.

Every completion of a query is a *full* universe window that satisfies all
active clauses and all fixed bindings at once, and whose target cell has a
canonical decimal spelling beginning with the query prefix.  Because each job's
universe is bounded (``PROTOCOL.md``: at most 65536 windows) feasibility is
decided by exhaustive, joint enumeration rather than by per-clause reasoning:
satisfying different clauses with incompatible future assignments is
insufficient here, so the masks of the whole theory are intersected first and
every candidate next token is tested against that single joint mask.
"""
from __future__ import annotations

import numpy as np

DIGITS = '0123456789'
NO_COMPLETION = {'count': 0, 'tokens': [], 'witness': None}


def canonical(value: int) -> str:
    """Canonical decimal spelling: no sign, no leading zeros, zero is '0'."""
    return str(int(value))


def names_canonical(text: str) -> bool:
    """True when ``text`` is the canonical spelling of some integer."""
    return bool(text) and (text == '0' or text[0] != '0')


class TheoryDecoder:
    """Answer prefix-extension queries against one conjunction of clauses."""

    def __init__(self, space, cell_of, ranks_of_value, falsify_universe):
        self.space = space
        self.cell_of = cell_of            # reference -> flattened cell index
        self.ranks_of_value = ranks_of_value  # cell -> {value: domain position}
        self.falsify = falsify_universe   # predicate -> universe boolean column
        self.theory = np.ones(space.size, dtype=bool)
        self._ranks = {}
        self._spelling = {}
        self._window_mask = {}

    def apply_clauses(self, clauses) -> None:
        """Conjoin every approved-and-learned clause into the theory mask."""
        for clause in clauses:
            falsified = None
            for predicate in clause:
                mask = self.falsify[predicate]
                falsified = mask if falsified is None else (falsified & mask)
            if falsified is not None:
                self.theory &= ~falsified

    # -- target helpers ----------------------------------------------------
    def target_ranks(self, cell: int) -> np.ndarray:
        cached = self._ranks.get(cell)
        if cached is None:
            cached = self.space.ranks(cell)
            self._ranks[cell] = cached
        return cached

    def spellings(self, cell: int) -> list[str]:
        cached = self._spelling.get(cell)
        if cached is None:
            cached = [canonical(value) for value in self.space.domains[cell].tolist()]
            self._spelling[cell] = cached
        return cached

    def ranks_with_prefix(self, cell: int, prefix: str) -> np.ndarray:
        """Domain positions whose canonical spelling starts with ``prefix``."""
        if not prefix:
            return np.arange(self.space.radices[cell], dtype=np.int64)
        hits = [rank for rank, text in enumerate(self.spellings(cell)) if text.startswith(prefix)]
        return np.asarray(hits, dtype=np.int64)

    def window_mask(self, cell: int, prefix: str) -> np.ndarray:
        """Universe windows whose ``cell`` spelling starts with ``prefix``."""
        key = (cell, prefix)
        cached = self._window_mask.get(key)
        if cached is None:
            positions = self.space.radices[cell]
            selection = np.zeros(positions, dtype=bool)
            ranks = self.ranks_with_prefix(cell, prefix)
            if ranks.size:
                selection[ranks] = True
            cached = selection[self.target_ranks(cell)]
            self._window_mask[key] = cached
        return cached

    # -- queries -----------------------------------------------------------
    def feasible(self, query) -> np.ndarray | None:
        """Boolean universe column of windows matching theory and fixed cells."""
        mask = self.theory
        for binding in query['fixed']:
            cell = self.cell_of(tuple(binding['ref']))
            rank = self.ranks_of_value[cell][binding['value']]
            mask = mask & (self.target_ranks(cell) == rank)
            if not mask.any():
                return None
        return mask

    def answer(self, query) -> dict:
        prefix = query['prefix']
        base = self.feasible(query)
        if base is None:
            return dict(NO_COMPLETION)
        target_cell = self.cell_of(tuple(query['target']))
        completions = base & self.window_mask(target_cell, prefix)
        count = int(completions.sum())
        if count == 0:
            return dict(NO_COMPLETION)
        witness = int(np.flatnonzero(completions)[0])
        hits = np.bincount(self.target_ranks(target_cell)[completions],
                           minlength=self.space.radices[target_cell])
        tokens = []
        for digit in DIGITS:
            ranks = self.ranks_with_prefix(target_cell, prefix + digit)
            if ranks.size and bool((hits[ranks] > 0).any()):
                tokens.append(digit)
        if names_canonical(prefix):
            rank = self.ranks_of_value[target_cell].get(int(prefix))
            if rank is not None and hits[rank] > 0:
                tokens.append('END')
        return {'count': count, 'tokens': tokens, 'witness': witness}
